Step 6: Service 계층에서 사용
package com.example.service
import com.example.domain.User
import com.example.repository.UserRepository
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
@Service
class UserService(
private val userRepository: UserRepository
) {
/**
* 사용자 생성
* createdAt, createdBy가 자동으로 설정됨
*/
@Transactional
fun createUser(name: String, email: String, age: Int): User {
val user = User(
name = name,
email = email,
age = age
)
return userRepository.save(user)
// 저장 시 자동으로:
// - createdAt = 현재 시각
// - createdBy = "admin" (현재 로그인 사용자)
// - updatedAt = 현재 시각
// - updatedBy = "admin"
}
/**
* 사용자 수정
* updatedAt, updatedBy가 자동으로 갱신됨
*/
@Transactional
fun updateUser(id: String, name: String): User {
val user = userRepository.findById(id)
.orElseThrow { IllegalArgumentException("User not found") }
val updated = user.copy(name = name)
return userRepository.save(updated)
// 저장 시 자동으로:
// - updatedAt = 현재 시각 (갱신)
// - updatedBy = "admin" (갱신)
// - createdAt, createdBy는 유지
}
}
